using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public sealed class CalculateLoyaltyDiscountAcceptanceTests
{
    private static LoyaltyDiscountQuote Quote(int subtotal, LoyaltyTier tier, string? promo = null) =>
        new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(subtotal, tier, promo));

    // S1 Member receives the loyalty discount of their tier
    [Theory]
    [InlineData(LoyaltyTier.Bronze, 500, 9500)]
    [InlineData(LoyaltyTier.Silver, 1000, 9000)]
    [InlineData(LoyaltyTier.Gold, 1500, 8500)]
    public void S1_MemberReceivesTierDiscount(LoyaltyTier tier, int discount, int total)
    {
        var quote = Quote(10000, tier);

        Assert.Equal(discount, quote.DiscountCents);
        Assert.Equal(total, quote.TotalCents);
    }

    // S2 Member's loyalty discount never exceeds 20.00 EUR
    [Theory]
    [InlineData(20000, LoyaltyTier.Gold, 2000, 18000)]
    [InlineData(30000, LoyaltyTier.Silver, 2000, 28000)]
    [InlineData(12000, LoyaltyTier.Gold, 1800, 10200)]
    public void S2_DiscountCappedAtTwentyEuros(int subtotal, LoyaltyTier tier, int discount, int total)
    {
        var quote = Quote(subtotal, tier);

        Assert.Equal(discount, quote.DiscountCents);
        Assert.Equal(total, quote.TotalCents);
    }

    // S3 Member gets no loyalty discount under a 30.00 EUR subtotal
    [Theory]
    [InlineData(2999, 0, 2999)]
    [InlineData(3000, 450, 2550)]
    public void S3_NoDiscountUnderThirtyEuros(int subtotal, int discount, int total)
    {
        var quote = Quote(subtotal, LoyaltyTier.Gold);

        Assert.Equal(discount, quote.DiscountCents);
        Assert.Equal(total, quote.TotalCents);
    }

    // S4 Member's WELCOME5 promo code takes 5.00 EUR off after the loyalty discount
    [Theory]
    [InlineData(10000, LoyaltyTier.Silver, 1500, 8500)]
    [InlineData(2000, LoyaltyTier.Bronze, 500, 1500)]
    public void S4_Welcome5TakesFiveEurosOffAfterLoyalty(int subtotal, LoyaltyTier tier, int discount, int total)
    {
        var quote = Quote(subtotal, tier, "WELCOME5");

        Assert.Equal(discount, quote.DiscountCents);
        Assert.Equal(total, quote.TotalCents);
    }

    // S5 Member's cap applies to the loyalty discount only, never to WELCOME5
    [Theory]
    [InlineData(20000, LoyaltyTier.Gold, 2500, 17500)]
    [InlineData(30000, LoyaltyTier.Silver, 2500, 27500)]
    public void S5_CapNeverAppliesToWelcome5(int subtotal, LoyaltyTier tier, int discount, int total)
    {
        var quote = Quote(subtotal, tier, "WELCOME5");

        Assert.Equal(discount, quote.DiscountCents);
        Assert.Equal(total, quote.TotalCents);
    }

    // S6 Member's promo code is accepted whatever its case
    [Theory]
    [InlineData("welcome5")]
    [InlineData("Welcome5")]
    public void S6_PromoCodeIgnoresCase(string code)
    {
        var quote = Quote(10000, LoyaltyTier.Silver, code);

        Assert.Equal(1500, quote.DiscountCents);
    }

    // S7 Member's SUMMER10 promo code takes 10 % off what is left, at most 15.00 EUR
    [Theory]
    [InlineData(10000, LoyaltyTier.Silver, 1900, 8100)]
    [InlineData(30000, LoyaltyTier.Bronze, 3000, 27000)]
    [InlineData(2000, LoyaltyTier.Gold, 200, 1800)]
    public void S7_Summer10TakesTenPercentOfWhatIsLeft(int subtotal, LoyaltyTier tier, int discount, int total)
    {
        var quote = Quote(subtotal, tier, "SUMMER10");

        Assert.Equal(discount, quote.DiscountCents);
        Assert.Equal(total, quote.TotalCents);
    }

    // S8 Member's unknown promo code is ignored
    [Fact]
    public void S8_UnknownPromoCodeIsIgnored()
    {
        var quote = Quote(10000, LoyaltyTier.Silver, "SPRING");

        Assert.Equal(1000, quote.DiscountCents);
        Assert.Equal(9000, quote.TotalCents);
    }

    // S9 Platinum member receives a 20 % loyalty discount
    [Theory]
    [InlineData(10000, 2000, 8000)]
    [InlineData(5000, 1000, 4000)]
    [InlineData(20000, 2000, 18000)]
    public void S9_PlatinumReceivesTwentyPercent(int subtotal, int discount, int total)
    {
        var quote = Quote(subtotal, LoyaltyTier.Platinum);

        Assert.Equal(discount, quote.DiscountCents);
        Assert.Equal(total, quote.TotalCents);
    }

    // S10 Member's discount never exceeds the subtotal
    [Theory]
    [InlineData(400, LoyaltyTier.Bronze, 400)]
    [InlineData(300, LoyaltyTier.Gold, 300)]
    public void S10_DiscountNeverExceedsSubtotal(int subtotal, LoyaltyTier tier, int discount)
    {
        var quote = Quote(subtotal, tier, "WELCOME5");

        Assert.Equal(discount, quote.DiscountCents);
        Assert.Equal(0, quote.TotalCents);
    }
}

